import "server-only";
import catalog from "@/data/source-snapshot/catalog.json";
import localeMap from "@/data/source-snapshot/locale-map.json";
import mediaMeta from "@/data/source-snapshot/media-meta.json";
import type { Locale } from "@/lib/i18n/config";
import { LOCALES } from "@/lib/i18n/config";
import { sanitizeRichText } from "./sanitize";
import type { CatalogCategory, CatalogImage, CatalogProduct, CatalogRepository, ContentStatus } from "./types";

/**
 * Sprint 1 catalog: the read-only audit snapshot of kornne.com (src/data/source-snapshot, generated by
 * scripts/audit/*). Unverified data — every page rendering it is noindex until Sprint 2 imports verified records.
 *
 * Prices: the Turkish record is the single price source for every locale (legacy EN/FR records carry
 * conflicting prices for 11 products — docs/audit/data-quality.md).
 */
type SnapshotProduct = (typeof catalog.products)[number];
type SnapshotTranslation = (typeof catalog.translations)[number];

const META = mediaMeta as Record<string, { width: number | null; height: number | null }>;

function toImage(url: string, alt: string): CatalogImage {
  const name = decodeURIComponent(new URL(url).pathname.replace(/^\/upload\//, ""));
  const m = META[name];
  return { src: `/upload/${encodeURIComponent(name)}`, alt, width: m?.width ?? null, height: m?.height ?? null };
}

const translationsById = new Map<string, SnapshotTranslation>(catalog.translations.map((t) => [`${t.locale}:${t.source_id}`, t]));
const mapByTr = new Map(localeMap.products.map((p) => [p.tr, p]));

function build(locale: Locale, p: SnapshotProduct): CatalogProduct {
  const map = mapByTr.get(p.source_id);
  const legacyId = locale === "en" ? map?.en : locale === "fr" ? map?.fr : null;
  const t = legacyId ? translationsById.get(`${locale}:${legacyId}`) : undefined;
  const contentStatus: ContentStatus = locale === "tr" ? "source" : t ? "legacy-translation" : "missing";
  const title = t?.title || p.title;
  const rawHtml = (t?.description_html ?? p.description_html) || "";
  const images = (p.images as string[]).map((src, i) => toImage(src, i === 0 ? title : `${title} – ${i + 1}`));
  const slugs: Partial<Record<Locale, string>> = { tr: p.slug };
  for (const l of LOCALES) {
    if (l === "tr") continue;
    const id = l === "en" ? map?.en : l === "fr" ? map?.fr : null;
    const tt = id ? translationsById.get(`${l}:${id}`) : undefined;
    slugs[l] = tt?.slug ?? p.slug;
  }
  return {
    id: `snapshot:${p.source_id}`,
    sourceId: p.source_id,
    relatedSourceIds: [],
    seoTitle: null,
    seoDescription: null,
    slug: slugs[locale] ?? p.slug,
    slugs,
    title,
    descriptionHtml: sanitizeRichText(rawHtml),
    descriptionText: (t?.description_text ?? p.description_text) || "",
    contentStatus,
    translatedLocales: ["tr", ...(map?.en && translationsById.has(`en:${map.en}`) ? (["en"] as const) : []), ...(map?.fr && translationsById.has(`fr:${map.fr}`) ? (["fr"] as const) : [])],
    images,
    currency: "TRY",
    // Sprint 2 rule: legacy prices are UNVERIFIED → never customer-facing (raw values stay in the snapshot / DB)
    priceMinor: null,
    compareAtMinor: null,
    priceVerified: false,
    vatIncluded: null,
    availability: null,
    brandName: null,
    mpn: null,
    gtin: null,
    pageLocale: contentStatus === "missing" ? "tr" : locale,
    categoryKeys: p.categories,
    primaryCategoryKey: ["mezbaha-ekipmanlari", "kurban-ekipmanlari", "robotik-sistemler"].find((k) => p.categories.includes(k)) ?? null,
    sortOrder: 0,
    specs: [],
    documents: [],
    variants: (p.variants ?? []).map((v) => ({ groupLabel: v.label, options: v.options })),
    sourceUrl: p.source_url,
    flags: p.flags,
    updatedAt: null,
  };
}

const cache = new Map<Locale, CatalogProduct[]>();
function productsFor(locale: Locale): CatalogProduct[] {
  let list = cache.get(locale);
  if (!list) {
    const order = new Map(catalog.home_featured.map((s, i) => [s, i]));
    list = catalog.products.map((p) => build(locale, p)).sort((a, b) => (order.get(a.slugs.tr!) ?? 999) - (order.get(b.slugs.tr!) ?? 999) || +a.sourceId - +b.sourceId);
    cache.set(locale, list);
  }
  return list;
}

function categoriesFor(locale: Locale): CatalogCategory[] {
  const products = productsFor(locale);
  return localeMap.categories.map((c) => {
    const loc = (c.locales as Record<string, { slug: string; name: string }>)[locale]!;
    const legacyTotal = catalog.categories.find((x) => x.slug === c.key)?.reported_total ?? "";
    return {
      key: c.key,
      isAllProducts: c.isAllProducts,
      name: loc.name,
      slug: loc.slug,
      slugs: Object.fromEntries(Object.entries(c.locales as Record<string, { slug: string }>).map(([l, v]) => [l, v.slug])),
      translatedLocales: ["tr"],
      productCount: c.isAllProducts ? products.length : products.filter((p) => p.categoryKeys.includes(c.key)).length,
      legacyReportedTotal: legacyTotal,
      seoTitle: null,
      seoDescription: null,
      description: null,
      updatedAt: null,
    };
  });
}

const fold = (s: string, locale: Locale) => s.toLocaleLowerCase(locale === "tr" ? "tr" : undefined).normalize("NFKD").replace(/\p{M}/gu, "");

export const snapshotRepository: CatalogRepository = {
  async listCategories(locale) {
    return categoriesFor(locale);
  },
  async getCategory(locale, slug) {
    const category = categoriesFor(locale).find((c) => c.slug === slug);
    if (!category) return null;
    const all = productsFor(locale);
    return { category, products: category.isAllProducts ? all : all.filter((p) => p.categoryKeys.includes(category.key)) };
  },
  async getProduct(locale, slug) {
    return productsFor(locale).find((p) => p.slug === slug) ?? null;
  },
  async listProducts(locale) {
    return productsFor(locale);
  },
  async search(locale, query) {
    const q = fold(query.trim(), locale);
    if (q.length < 2) return [];
    const terms = q.split(/\s+/);
    return productsFor(locale).filter((p) => {
      const hay = fold(`${p.title} ${p.descriptionText}`, locale);
      return terms.every((t) => hay.includes(t));
    });
  },
};
